    # Check for exactly one '@' character
    if s.count('@') != 1:
        return False

    # Split the string into local and domain parts
    local_part, domain_part = s.split('@')

    # Validate the local part
    if not local_part[0].isalpha() or not local_part[-1].isalpha():
        return False
    for char in local_part[1:-1]:
        if not char.isalnum() and char not in ['.', '_', '-']:
            return False

    # Validate the domain part
    if len(domain_part) < 2:
        return False
    for i in range(len(domain_part)):
        if not domain_part[i].isalnum() and domain_part[i] not in ['.', '_']:
            return False
        if i > 0 and domain_part[i] == '.' and not domain_part[i - 1].isalnum():
            return False
        if i < len(domain_part) - 1 and domain_part[i] == '.' and not domain_part[i + 1].isalnum():
            return False

    return True
```

